e_code\":\"sk\",\"enabled\":true,\"url_path\":\"/sk/library/bg/6/8/\"},{\"display_name\":\"Slovenščina (Slovenian)\",\"language_code\":\"sl\",\"enabled\":true,\"url_path\":\"/sl/library/bg/6/8/\"},{\"display_name\":\"Українська мова (Ukrainian)\",\"language_code\":\"uk\",\"enabled\":true,\"url_path\":\"/uk/library/bg/6/8/\"},{\"display_name\":\"isiZulu (Zulu)\",\"language_code\":\"zu\",\"enabled\":false,\"url_path\":\"/zu/\"}],\"breadcrumb\":[{\"url_path\":\"/en/library/\",\"title\":\"Library\"},{\"url_path\":\"/en/library/bg/\",\"title\":\"Bhagavad-gītā As It Is\"},{\"url_path\":\"/en/library/bg/6/\",\"title\":\"Chapter Six: Dhyāna-yoga\"}],\"url_path\":\"/en/library/bg/6/8/\",\"bb\":1594,\"has_advanced_view\":false,\"pager\":{\"previous\":{\"url_path\":\"/en/library/bg/6/7/\",\"title\":\"TEXT 7\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/6/9/\",\"title\":\"TEXT 9\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":1803,\"bb\":568115,\"url_path\":\"/en/library/bg/6/8/devanagari/\",\"body_final\":\"ज्ञानविज्ञानतृप्‍तात्मा कूटस्थो विजितेन्द्रिय: ।
युक्त इत्युच्यते योगी समलोष्ट्राश्मकाञ्चन: ॥ ८ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":1804,\"bb\":1595,\"url_path\":\"/en/library/bg/6/8/b1595/\",\"body_value\":\"jñāna-vijñāna-tṛptātmā
kūṭa-stho vijitendriyaḥ
yukta ity ucyate yogī
sama-loṣṭrāśma-kāñcanaḥ\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":1805,\"bb\":1596,\"url_path\":\"/en/library/bg/6/8/b1596/\",\"shadow_value\":\"jñāna – by acquired knowledge; vijñāna – and realized knowledge; tṛpta – satisfied; ātmā – a living entity; kūṭa-sthaḥ – spiritually situated; vijita-indriyaḥ – sensually controlled; yuktaḥ – competent for self-realization; iti – thus; ucyate – is said; yogī – a mystic; sama – equipoised; loṣṭra – pebbles; aśma – stone; kāñcanaḥ – gold.\",\"word_for_word_value\":[{\"word\":\"jñāna\",\"translation\":\"by acquired knowledge\"},{\"word\":\"vijñāna\",\"translation\":\"and realized knowledge\"},{\"word\":\"tṛpta\",\"translation\":\"satisfied\"},{\"word\":\"ātmā\",\"translation\":\"a living entity\"},{\"word\":\"kūṭa-sthaḥ\",\"translation\":\"spiritually situated\"},{\"word\":\"vijita-indriyaḥ\",\"translation\":\"sensually controlled\"},{\"word\":\"yuktaḥ\",\"translation\":\"competent for self-realization\"},{\"word\":\"iti\",\"translation\":\"thus\"},{\"word\":\"ucyate\",\"translation\":\"is said\"},{\"word\":\"yogī\",\"translation\":\"a mystic\"},{\"word\":\"sama\",\"translation\":\"equipoised\"},{\"word\":\"loṣṭra\",\"translation\":\"pebbles\"},{\"word\":\"aśma\",\"translation\":\"stone\"},{\"word\":\"kāñcanaḥ\",\"translation\":\"gold\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":1806,\"bb\":1597,\"url_path\":\"/en/library/bg/6/8/b1597/\",\"body_value\":\"A person is said to be established in self-realization and is called a yogī [or mystic] when he is fully satisfied by virtue of acquired knowledge and realization. Such a person is situated in transcendence and is self-controlled. He sees everything – whether it be pebbles, stones or gold – as the same.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":1807,\"bb\":1598,\"url_path\":\"/en/library/bg/6/8/b1598/\",\"body_value\":\"Book knowledge without realization of the Supreme Truth is useless. This is stated as follows:\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":1808,\"bb\":1599,\"url_path\":\"/en/library/bg/6/8/b1599/\",\"body_value\":\"ataḥ śrī-kṛṣṇa-nāmādi
na bhaved grāhyam indriyaiḥ
sevonmukhe hi jihvādau
svayam eva sphuraty adaḥ\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":1809,\"bb\":1600,\"url_path\":\"/en/library/bg/6/8/b1600/\",\"body_value\":\"“No one can understand the transcendental nature of the name, form, quality and pastimes of Śrī Kṛṣṇa through his materially contaminated senses. Only when one becomes spiritually saturated by transcendental service to the Lord are the transcendental name, form, quality and pastimes of the Lord revealed to him.” (Bhakti-rasāmṛta-sindhu 1.2.234)\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":1810,\"bb\":1601,\"url_path\":\"/en/library/bg/6/8/b1601/\",\"body_value\":\"This Bhagavad-gītā is the science of Kṛṣṇa consciousness. No one can become Kṛṣṇa conscious simply by mundane scholarship. One must be fortunate enough to associate with a person who is in pure consciousness. A Kṛṣṇa conscious person has realized knowledge, by the grace of Kṛṣṇa, because he is satisfied with pure devotional service. By realized knowledge, one becomes perfect. By transcendental knowledge one can remain steady in his convictions, but by mere academic knowledge one can be easily deluded and confused by apparent contradictions. It is the realized soul who is actually self-controlled, because he is surrendered to Kṛṣṇa. He is transcendental because he has nothing to do with mundane scholarship. For him mundane scholarship and mental speculation, which may be as good as gold to others, are of no greater value than pebbles or stones.\"}]}],\"short_title\":\"Bg. 6.8\",\"medium_title\":\"Bhagavad-gītā As It Is 6.8\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L25\",\"$L26\",\"$L27\"]}]\n"])self.__next_f.push([1,"29:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-z